# Good: specific, safe fields, and ids instead of personal data where possible
logger.info("login_failed", extra={
    "user_id": user.id if user else None,
    "ip": request.remote_addr,
    "request_id": request_id,
    "reason": "bad_password",
})

# Safety net: redact well-known sensitive keys before anything is written
SENSITIVE = {"password", "token", "authorization", "cookie", "card_number"}

def redact(fields: dict) -> dict:
    return {k: ("[REDACTED]" if k.lower() in SENSITIVE else v) for k, v in fields.items()}

